prog='''def transform(grid):
    def objs(g):
        h,w=len(g),len(g[0]); seen=set(); res=[]
        for i in range(h):
            for j in range(w):
                if g[i][j] and (i,j) not in seen:
                    col=g[i][j]; st=[(i,j)]; comp=set()
                    while st:
                        y,x=st.pop()
                        if (y,x) in comp: continue
                        comp.add((y,x))
                        for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                            a,b=y+dy,x+dx
                            if 0<=a<h and 0<=b<w and g[a][b]==col and (a,b) not in comp: st.append((a,b))
                    seen|=comp
                    res.append((col,sorted(comp)))
        return res
    def norm(cells):
        ys=[c[0] for c in cells]; xs=[c[1] for c in cells]
        return tuple(sorted((y-min(ys),x-min(xs)) for y,x in cells))
    out=[row[:] for row in grid]
    groups={}
    for col,c in objs(grid): groups.setdefault(norm(c),[]).append((col,c))
    for shape,mem in groups.items():
        if len(mem)>1:
            tgt=max(m[0] for m in mem)
            for col,c in mem:
                if col!=tgt:
                    for y,x in c: out[y][x]=tgt
    return out
'''
